-- Correction 2026-09-14, access.staging. The owner chose public staging on 14 September 2026 and the
-- Basic-auth password was removed, so the launch-pass note above ("Becomes Ready when
-- STAGING_ACCESS_PASSWORD is set") describes an environment that no longer exists. History stays
-- append-only: the new note is a new change with its own event, and it lands only while the
-- launch-pass change is still the latest one, so a later edit by a person is never overwritten.
-- Status and evidence are untouched. Nothing here makes the control ready.
UPDATE operational_controls SET note = 'Superseded 2026-09-14: the owner chose public staging and the Basic-auth password was removed, so the old requirement (restricted to approved testers) is replaced, not met. The control is now the public/private boundary: public pages answer 200 with noindex, staff pages redirect to staff sign-in, and private APIs answer 401 to anonymous requests. The mode is declared as STAGING_ACCESS_OPEN in wrangler.jsonc env.staging, and scripts/staging-access-check.mjs proves the boundary as the last step of Deploy staging (tests/staging-access-check.test.ts). Evidence for Ready: a green Deploy staging run with that step passing. Blocked until the CLOUDFLARE_API_TOKEN repository secret exists (c16-new-2); delete the STAGING_ACCESS_OPEN Worker secret immediately before that deploy.', last_change_id = 'oce_5f0d66c9e9c7658e9ae617c1', updated_by = 'Access-boundary reconciliation 2026-09-14 (Claude for Ammre, under owner authority; not a staff login)', updated_at = 1789407499 WHERE key = 'access.staging' AND last_change_id = 'oce_10132f12a1e5547560f41834';
INSERT OR IGNORE INTO operational_control_events (id, control_key, from_status, to_status, owner_id, owner_name, due_on, evidence_url, note, actor, created_at) SELECT last_change_id, key, status, status, owner_id, owner_name, due_on, evidence_url, note, updated_by, updated_at FROM operational_controls WHERE key = 'access.staging' AND last_change_id = 'oce_5f0d66c9e9c7658e9ae617c1';
